<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>City Skyline Day‑Night Cycle</title>
<style>body{margin:0;background:#000}</style>
</head>
<body>
<canvas id="sky" width="800" height="400"></canvas>
<script>
const canvas=document.getElementById('sky');
const ctx=canvas.getContext('2d');
const W=canvas.width, H=canvas.height;
const DAY_COLOR={r:135,g:206,b:235};  // sky blue
const NIGHT_COLOR={r:10,g:10,b:30};   // dark navy
const SUN_COLOR='rgb(255,223,0)';
const MOON_COLOR='rgb(220,220,220)';
const BUILDING_COLOR='rgb(50,50,70)';
const WINDOW_OFF='rgb(10,10,10)';
const WINDOW_ON='rgb(255,255,100)';
const STARS_COUNT=200;
const stars=[];

// generate stars
for(let i=0;i<STARS_COUNT;i++){
    stars.push({
        x:Math.random()*W,
        y:Math.random()*H/2,   // only upper half
        r:1+Math.random()*2
    });
}

// define buildings (x,width,height)
const buildings=[
    {x:0,w:120,h:250},
    {x:140,w:90,h:180},
    {x:260,w:110,h:300},
    {x:380,w:80,h:200},
    {x:500,w:140,h:260},
    {x:640,w:90,h:190}
];

function lerp(a,b,t){return a+(b-a)*t;}
function rgb(r,g,b){return `rgb(${r},${g},${b})`}

function drawSky(progress){
    let factor, color;
    if(progress<=0.5){ // day -> night
        factor=progress/0.5;
        color={
            r:lerp(DAY_COLOR.r,NIGHT_COLOR.r,factor),
            g:lerp(DAY_COLOR.g,NIGHT_COLOR.g,factor),
            b:lerp(DAY_COLOR.b,NIGHT_COLOR.b,factor)
        };
    }else{ // night -> day
        factor=(progress-0.5)/0.5;
        color={
            r:lerp(NIGHT_COLOR.r,DAY_COLOR.r,factor),
            g:lerp(NIGHT_COLOR.g,DAY_COLOR.g,factor),
            b:lerp(NIGHT_COLOR.b,DAY_COLOR.b,factor)
        };
    }
    ctx.fillStyle=rgb(Math.round(color.r),Math.round(color.g),Math.round(color.b));
    ctx.fillRect(0,0,W,H);
}

function drawSunMoon(progress){
    const half=0.5;
    if(progress<=half){ // sun
        const t=progress/half; // 0..1
        const angle=Math.PI*t; // 0..π
        const x=W*t;
        const y=(H/2)*(1-Math.cos(angle));
        ctx.beginPath();
        ctx.arc(x,y,30,0,2*Math.PI);
        ctx.fillStyle=SUN_COLOR;
        ctx.fill();
    }else{ // moon
        const t=(progress-half)/half; // 0..1
        const angle=Math.PI*t;
        const x=W*(1-t);
        const y=(H/2)*(1-Math.cos(angle));
        ctx.beginPath();
        ctx.arc(x,y,25,0,2*Math.PI);
        ctx.fillStyle=MOON_COLOR;
        ctx.fill();
    }
}

function drawStars(progress){
    if(progress<=0.5)return;
    const alpha=(progress-0.5)/0.5; // fade in
    ctx.globalAlpha=alpha;
    for(const s of stars){
        ctx.beginPath();
        ctx.arc(s.x,s.y,s.r,0,2*Math.PI);
        ctx.fillStyle='white';
        ctx.fill();
    }
    ctx.globalAlpha=1;
}

function drawBuildings(progress){
    for(const b of buildings){
        const y=H-b.h;
        ctx.fillStyle=BUILDING_COLOR;
        ctx.fillRect(b.x, y, b.w, b.h);
        // windows
        const rows=Math.floor(b.h/30);
        const cols=Math.floor(b.w/20);
        const winW=b.w/cols-2;
        const winH=b.h/rows-2;
        for(let r=0;r<rows;r++){
            for(let c=0;c<cols;c++){
                const winX=b.x+2+c*(winW+2);
                const winY=y+2+r*(winH+2);
                if(progress>0.5 && Math.random()<0.3){
                    ctx.fillStyle=WINDOW_ON;
                }else{
                    ctx.fillStyle=WINDOW_OFF;
                }
                ctx.fillRect(winX,winY,winW,winH);
            }
        }
    }
}

let start=performance.now();
function loop(){
    const now=performance.now();
    let progress=((now-start)%10000)/10000; // 0..1
    drawSky(progress);
    drawSunMoon(progress);
    drawStars(progress);
    drawBuildings(progress);
    requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
</body>
</html>
```

This file animates a day‑night cycle by interpolating sky colors, moving sun and moon along arcs, fading in stars, and lighting building windows during the nighttime, all driven by a 10‑second loop using `requestAnimationFrame`.
